<template>
  <div class="printable-shell">
    <main class="printable-document printable-technologies" data-technology-profile-root>
      <header class="technology-header">
        <h1>{{ model.profile.name }}</h1>
        <p class="technology-role">{{ model.profile.title }}</p>
        <h2>{{ profile.copy.title }}</h2>
        <p>{{ profile.copy.introduction }}</p>
        <p class="technology-contacts">
          <a :href="email.url">{{ email.value }}</a> ·
          <a href="https://renetik.com/services/cv/">renetik.com</a> ·
          <a href="https://www.linkedin.com/in/renetik">linkedin.com/in/renetik</a>
        </p>
        <p class="technology-updated">{{ profile.copy.updatedLabel }}: {{ profile.updatedOn }}</p>
      </header>

      <aside class="technology-assessment">
        <h3>{{ profile.copy.legendTitle }}</h3>
        <p>{{ profile.copy.assessmentNote }}</p>
        <dl>
          <div :key="id" v-for="(level, id) in profile.copy.levels">
            <dt>{{ level.label }}</dt>
            <dd>{{ level.description }}</dd>
          </div>
        </dl>
      </aside>

      <section :key="group.id" class="technology-group" v-for="group in profile.groups">
        <table>
          <caption class="technology-caption">{{ group.title }}</caption>
          <colgroup><col class="technology-name"><col class="technology-level"><col class="technology-years"><col></colgroup>
          <thead>
            <tr><th class="technology-group-title" colspan="4"><h3>{{ group.title }}</h3></th></tr>
            <tr>
              <th scope="col">{{ profile.copy.technologyLabel }}</th>
              <th scope="col">{{ profile.copy.levelLabel }}</th>
              <th scope="col">{{ profile.copy.yearsLabel }}</th>
              <th scope="col">{{ profile.copy.descriptionLabel }}</th>
            </tr>
          </thead>
          <tbody>
            <tr :data-technology-id="entry.id" :key="entry.id" v-for="entry in group.entries">
              <th scope="row">{{ entry.name }}</th>
              <td>{{ entry.levelLabel }}</td>
              <td class="technology-years-value">{{ entry.yearsLabel }}</td>
              <td>{{ entry.description }}</td>
            </tr>
          </tbody>
        </table>
      </section>
    </main>
  </div>
</template>

<script lang="ts">
import {Component} from 'vue-property-decorator'
import {PortalVueBase} from '@/view/PortalVueBase'
import {ProfileContactIds} from '@/model/Data/ProfileData'
import {pageMetaInfo} from '@/model/Seo'

@Component
export default class PrintableTechnologies extends PortalVueBase {
  get profile() { return this.model.technologyProfile }
  get email() { return this.model.profile.contact(ProfileContactIds.email) }

  mounted() {
    document.body.classList.add('cv-paper-print')
  }

  beforeDestroy() {
    document.body.classList.remove('cv-paper-print')
  }

  metaInfo(): any {
    const info = pageMetaInfo(
      this.profile.copy.title, this.profile.copy.introduction,
      this.constants.technologiesPrintPath, this.model.cv.photo.src
    )
    return {...info, meta: [...info.meta, {vmid: 'robots', name: 'robots', content: 'noindex'}]}
  }
}
</script>

